-- The 40-minute mock exam has no artificial two-minute answer cutoff.
alter table public.audio_uploads drop constraint audio_uploads_duration_ms_check;
alter table public.audio_uploads add constraint audio_uploads_duration_ms_check check(duration_ms between 1000 and 2400000);
alter table public.analyses drop constraint analyses_audio_duration_ms_check;
alter table public.analyses add constraint analyses_audio_duration_ms_check check(audio_duration_ms between 1000 and 2400000);
insert into public.scenarios(id,mode,level,title,prompt,goals,topic,question_type) select id,mode,level,title,prompt,goals,topic,question_type from jsonb_to_recordset('[{"id": "b7cb6c8f-def1-5c54-ac39-77439f16882e", "mode": "opic", "topic": "park", "question_type": "opinion", "title": "공공장소 · 사회적 역할", "prompt": "Why are public parks important in a city? Discuss a challenge in maintaining them and suggest a way to address it.", "goals": ["사회적 주제 설명", "근거와 대안"], "level": "intermediate"}, {"id": "29c34921-bba1-5e5d-8e15-aca6adcb0f39", "mode": "opic", "topic": "home", "question_type": "opinion", "title": "주거 · 변화와 선택", "prompt": "How have housing preferences changed in recent years? Explain possible reasons and discuss a trade-off people face when choosing a home.", "goals": ["사회적 주제 설명", "근거와 대안"], "level": "intermediate"}]'::jsonb) as x(id uuid,mode text,level text,title text,prompt text,goals text[],topic text,question_type text) on conflict(id) do nothing;
